Problem Set:

1. Array Manipulation: Given an array of integers, create a function that reverses the order of the elements in the array.

Solution:

function reverseArray(arr) {
  const reversedArr = [];

  for (let i = arr.length - 1; i >= 0; i--) {
    reversedArr.push(arr[i]);
  }

  return reversedArr;
}

console.log(reverseArray([1, 2, 3, 4, 5])); // Output: [5, 4, 3, 2, 1]

2. Sorting Algorithms: Write a function to implement the selection sort algorithm to sort an array of integers in ascending order.

Solution:

function selectionSort(arr) {
  for (let i = 0; i < arr.length; i++) {
    let minIndex = i;
    for (let j = i + 1; j < arr.length; j++) {
      if (arr[j] < arr[minIndex]) {
        minIndex = j;
      }
    }

    if (minIndex !== i) {
      [arr[i], arr[minIndex]] = [arr[minIndex], arr[i]];
    }
  }

  return arr;
}

console.log(selectionSort([5, 2, 4, 6, 1, 3])); // Output: [1, 2, 3, 4, 5, 6]

3. Basic Recursion: Write a recursive function to calculate the factorial of a given positive integer.

Solution:

function factorial(n) {
  if (n === 0) {
    return 1;
  }

  return n * factorial(n - 1);
}

console.log(factorial(5)); // Output: 120

